const PERMITIDO = 'https://app.exemplo.com';
export function tratarCallback(req, res) {
  const destino = req.query.redirect_uri;
  if (destino && destino.startsWith(PERMITIDO)) {
    return res.redirect(destino + '?code=' + req.query.code);
  }
  return res.status(400).end();
}

